steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issue(identifier: \"MOB-42\") { id identifier name subIssues { nodes { id identifier name estimate dueDate priority priorityName } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { number: { eq: 42 } }) { nodes { id identifier title estimate dueDate priority priorityName children { nodes { id identifier title estimate dueDate priority priorityName } } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { number: { eq: 42 } }) { nodes { id identifier title estimate dueDate priority children { nodes { id identifier title estimate dueDate priority } } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "mutation": "mutation { issueUpdate(id: \"i-mob-50\", input: { priority: 2 }) { success identifier priority } }"
  }'
